package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"database/sql"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"strconv"
	"strings"
	"time"
)

const maxBodyBytes = 1 << 20 // webhook events are expected to be small; avoid unbounded reads.

type Event struct {
	ID      string          `json:"id"`
	Type    string          `json:"type"`
	Created int64           `json:"created"`
	Payload json.RawMessage `json:"-"`
}

type EventStore interface {
	StoreEvent(context.Context, Event) error
}

type PostgresStore struct {
	DB *sql.DB
}

const createEventsTableSQL = `
CREATE TABLE IF NOT EXISTS events (
    id TEXT PRIMARY KEY,
    type TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL,
    payload JSONB NOT NULL
)`

func CreateEventsTable(ctx context.Context, db *sql.DB) error {
	_, err := db.ExecContext(ctx, createEventsTableSQL)
	return err
}

func (s PostgresStore) StoreEvent(ctx context.Context, event Event) error {
	_, err := s.DB.ExecContext(ctx, `
INSERT INTO events (id, type, created_at, payload)
VALUES ($1, $2, $3, $4::jsonb)
ON CONFLICT (id) DO UPDATE
SET type = EXCLUDED.type, created_at = EXCLUDED.created_at, payload = EXCLUDED.payload`,
		event.ID, event.Type, time.Unix(event.Created, 0).UTC(), []byte(event.Payload))
	return err
}

type webhookHandler struct {
	secret []byte
	store  EventStore
}

func NewHandler(secret string, store EventStore) http.Handler {
	return &webhookHandler{secret: []byte(secret), store: store}
}

func (h *webhookHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	switch {
	case r.Method == http.MethodGet && r.URL.Path == "/healthz":
		w.WriteHeader(http.StatusOK)
	case r.Method == http.MethodPost && r.URL.Path == "/webhooks":
		h.handleWebhook(w, r)
	default:
		http.NotFound(w, r)
	}
}

func (h *webhookHandler) handleWebhook(w http.ResponseWriter, r *http.Request) {
	body, err := io.ReadAll(http.MaxBytesReader(w, r.Body, maxBodyBytes))
	if err != nil {
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	if !verifySignature(r.Header.Get("Signature"), body, h.secret) {
		http.Error(w, "invalid signature", http.StatusBadRequest)
		return
	}

	var event Event
	if err := json.Unmarshal(body, &event); err != nil || event.ID == "" || event.Type == "" {
		http.Error(w, "invalid event payload", http.StatusBadRequest)
		return
	}
	event.Payload = append(event.Payload[:0], body...)

	if err := h.store.StoreEvent(r.Context(), event); err != nil {
		http.Error(w, "could not store event", http.StatusInternalServerError)
		return
	}
	w.WriteHeader(http.StatusOK)
}

// verifySignature accepts the comma-separated Signature header documented by the API.
func verifySignature(header string, body, secret []byte) bool {
	var timestamp, signature string
	for _, part := range strings.Split(header, ",") {
		key, value, ok := strings.Cut(strings.TrimSpace(part), "=")
		if !ok {
			continue
		}
		switch key {
		case "t":
			timestamp = value
		case "v1":
			signature = value
		}
	}
	if timestamp == "" || signature == "" {
		return false
	}
	if _, err := strconv.ParseInt(timestamp, 10, 64); err != nil {
		return false
	}
	provided, err := hex.DecodeString(signature)
	if err != nil {
		return false
	}

	mac := hmac.New(sha256.New, secret)
	_, _ = fmt.Fprintf(mac, "%s.", timestamp)
	_, _ = mac.Write(body)
	return hmac.Equal(mac.Sum(nil), provided)
}
package main

import (
	"context"
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

type memoryStore struct {
	events []Event
	err    error
}

func (s *memoryStore) StoreEvent(_ context.Context, event Event) error {
	if s.err != nil {
		return s.err
	}
	s.events = append(s.events, event)
	return nil
}

func signedRequest(t *testing.T, secret, body string) *http.Request {
	t.Helper()
	timestamp := "1735689600"
	mac := hmac.New(sha256.New, []byte(secret))
	_, _ = mac.Write([]byte(timestamp + "." + body))
	req := httptest.NewRequest(http.MethodPost, "/webhooks", strings.NewReader(body))
	req.Header.Set("Signature", "t="+timestamp+",v1="+hex.EncodeToString(mac.Sum(nil)))
	return req
}

func TestHealthz(t *testing.T) {
	rr := httptest.NewRecorder()
	NewHandler("secret", &memoryStore{}).ServeHTTP(rr, httptest.NewRequest(http.MethodGet, "/healthz", nil))
	if rr.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200", rr.Code)
	}
}

func TestWebhookStoresVerifiedEvent(t *testing.T) {
	store := &memoryStore{}
	body := `{"id":"evt_0001","type":"customer.created","created":1735689600,"data":{"object":{"id":"cus_1"}}}`
	rr := httptest.NewRecorder()
	NewHandler("top-secret", store).ServeHTTP(rr, signedRequest(t, "top-secret", body))
	if rr.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200; body: %s", rr.Code, rr.Body.String())
	}
	if len(store.events) != 1 {
		t.Fatalf("stored events = %d, want 1", len(store.events))
	}
	event := store.events[0]
	if event.ID != "evt_0001" || event.Type != "customer.created" || event.Created != 1735689600 || string(event.Payload) != body {
		t.Fatalf("stored event = %#v", event)
	}
}

func TestWebhookRejectsInvalidSignature(t *testing.T) {
	store := &memoryStore{}
	body := `{"id":"evt_0001","type":"customer.created","created":1735689600}`
	req := signedRequest(t, "right-secret", body)
	rr := httptest.NewRecorder()
	NewHandler("wrong-secret", store).ServeHTTP(rr, req)
	if rr.Code != http.StatusBadRequest {
		t.Fatalf("status = %d, want 400", rr.Code)
	}
	if len(store.events) != 0 {
		t.Fatal("event was stored despite an invalid signature")
	}
}

func TestWebhookOnlyAcknowledgesAfterStorage(t *testing.T) {
	body := `{"id":"evt_0001","type":"customer.created","created":1735689600}`
	rr := httptest.NewRecorder()
	NewHandler("secret", &memoryStore{err: errors.New("database unavailable")}).ServeHTTP(rr, signedRequest(t, "secret", body))
	if rr.Code != http.StatusInternalServerError {
		t.Fatalf("status = %d, want 500", rr.Code)
	}
}
